def p(text,style='BodyCustom'):return Paragraph(text,styles[style])
def h(text):return p(text,'SectionCustom')
def table(rows,widths):
    data=[[p(str(x),'CellHead' if i==0 else 'CellCustom') for x in row] for i,row in enumerate(rows)]
    t=Table(data,colWidths=widths,hAlign='LEFT',repeatRows=1)
    t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),NAVY),('ROWBACKGROUNDS',(0,1),(-1,-1),[colors.white,LIGHT]),('VALIGN',(0,0),(-1,-1),'TOP'),('LEFTPADDING',(0,0),(-1,-1),8),('RIGHTPADDING',(0,0),(-1,-1),8),('TOPPADDING',(0,0),(-1,-1),6),('BOTTOMPADDING',(0,0),(-1,-1),6),('LINEBELOW',(0,-1),(-1,-1),.4,colors.HexColor('#CCD7DE'))]))
    return t

class Bars(Flowable):
    def __init__(self):Flowable.__init__(self);self.width=490;self.height=127
    def draw(self):
        c=self.canv
        values=[('Repetition',16/70,GRAY),('Systematic RLNC',69/70,TEAL),('MDS control',1,NAVY)]
        for j,(label,value,color) in enumerate(values):
            y=92-j*34;c.setFont('Helvetica',9);c.setFillColor(NAVY);c.drawString(0,y+6,label)
            c.setFillColor(LIGHT);c.rect(115,y,310,20,fill=1,stroke=0)
            c.setFillColor(color);c.rect(115,y,310*value,20,fill=1,stroke=0)
            c.setFillColor(NAVY);c.setFont('Helvetica-Bold',9);c.drawRightString(490,y+6,f'{value:.1%}')

def footer(c,doc):
    c.setStrokeColor(colors.HexColor('#CEDAE1'));c.line(48, forty:=40,547,forty)
    c.setFont('Helvetica',8);c.setFillColor(GRAY);c.drawString(48,27,'WATERMARKING / PILOT DECISION REPORT / 04 OCT 2026');c.drawRightString(547,27,str(doc.page))
    if doc.page>1:c.setFont('Helvetica-Bold',8);c.drawString(48,811,'RLNC SPATIAL CODING / PRELIMINARY EVIDENCE')

story=[]
story += [p('PILOT STUDY  /  METHOD V0.1','SmallCustom'),p('Can RLNC improve\nimage watermark recovery?'.replace('\n','<br/>'),'TitleCustom'),p('A reproducible test of the latest proposed DWT-DCT / WAM + RLNC route, with a strong repetition baseline and an MDS control.','Deck')]
story += [table([['Decision','Evidence status'],['Do not finalize the method yet','Coding-layer gains are real in the erasure model. No gain over strong repetition was observed in the executed image-attack suite.']], [178,321]),Spacer(1,10)]
story += [h('What was actually executed'),p('A NumPy Haar-DWT + DCT-QIM prototype was run on <b>10 deterministic synthetic fixtures</b>, with 3 independent payloads each, 4 coding methods and 4,320 paired image-attack observations. These are 30 payload/image cases, not 4,320 independent images. The official invisible-watermark implementation and WAM were <b>not run</b>: required dependencies were unavailable and network downloads timed out.')]
story += [h('Three findings that change the decision'),p('<b>1. Erasure coding has a clear mechanism.</b> With exactly four of eight error-free packets retained, exhaustive recovery was 22.86% for repetition, 98.57% for this fixed RLNC matrix and 100% for MDS. The RLNC gain is +75.71 percentage points, but this is a coding-only result, not crop robustness.'),p('<b>2. Fair spatial repetition removes the apparent crop gain.</b> On all tested aligned 50% and 75% crops, repetition, RLNC and MDS all achieved 100% complete payload recovery, including the JPEG Q75/Q50 combinations. All RLNC-minus-repetition recovery differences in the executed image suite were zero.'),p('<b>3. Localization remains the bottleneck.</b> Arbitrary-offset crops retaining approximately 75% of the area and unregistered 2-degree rotations both gave 0% recovery for all methods. RLNC cannot restore synchronization or recover from fewer than four usable packets.')]
story += [h('Deliverable decision'),p('Retain the modular coding-wrapper idea as a <b>research hypothesis</b>. Do not claim a validated crop-robust method or cross-backbone generalization. In accordance with the requested sequence, an English proposal is deferred until the validation gate on page 4 is met.'),p('Source context: latest turn of the referenced conversation, "Finalizing the Watermark Method"; course requirements from IMG_2707.jpg. The conversation was treated as a hypothesis source, not experimental evidence.','SmallCustom')]
story += [PageBreak(),p('01 / Experimental design','TitleCustom')]
story += [h('Packet contract and equal budget'),p('Each 64-bit payload is split into four 16-bit source symbols, represented as a 4 x 2 byte matrix S. Coding uses GF(256), polynomial 0x11d, independently on the two byte columns. Eight spatial packets are embedded in a 2 x 4 grid of 256 x 256 tiles on a 1024 x 512 image.')]
story += [table([['Packet field','Bits','Purpose'],['Packet ID','8','Index into a public, fixed coefficient table'],['Coded symbol','16','Two bytes: P_i = sum_j a_ij S_j over GF(256)'],['CRC-8','8','Polynomial 0x07, initial value 0; covers ID and symbol'],['Total per packet / image','32 / 256','Same gross bit budget and tile support in every arm']],[108,63,328])]
story += [p('Coefficients are not carried in each packet: the experiment assumes both sides know the matrix, code family and grid configuration. This overhead assumption must remain explicit. CRC checks accidental corruption; it provides no authentication.','SmallCustom')]
story += [h('Controls designed to avoid a weak baseline'),table([['Arm','Definition'],['Raw padded reference','Identity rows in slots 0-3; slots 4-7 embed zero-symbol packets. Same physical budget, but no useful outer redundancy.'],['Repetition','Source IDs [0,1,2,3; 2,3,0,1]. Every aligned rectangle containing at least four tiles contains all four source symbols.'],['Systematic RLNC','Four identity rows plus four pseudorandom rows, seed 20261004. Coefficients were fixed before measurement.'],['MDS control','Vandermonde rows [1,x,x^2,x^3] for x=1,...,8. Included because finite-field erasure coding is not unique to RLNC.']],[112,387])]
story += [h('Image channel and decoder'),p('The offline prototype embeds a bit by quantizing the (1,2) DCT coefficient of each 8 x 8 Haar low-pass block with step 80. A packet bit receives eight within-tile repetitions. Extraction pools bounded soft evidence, validates CRC and performs finite-field elimination only when four independent, consistent equations exist. Ground-truth payloads are used for scoring only.'),p('The NumPy prototype differs from ShieldMnt dwtDct [1]; its measurements must not be attributed to that library. Synthetic fixtures cover gradients, waves, textures, shapes, text and a drawn landscape. No natural-image or learned-backbone performance is established.','SmallCustom')]
story += [h('Quality at the same embedding strength'),p('Mean PSNR / SSIM: raw 39.977 dB / 0.950792; repetition 39.968 dB / 0.950808; RLNC 39.945 dB / 0.950517; MDS 39.954 dB / 0.950600.')]
story += [p('RLNC vs repetition: -0.023 dB PSNR and -0.000290 SSIM. SSIM uses valid 7 x 7 uniform windows, sample covariance and per-channel averaging; PSNR uses an 8-bit range of 255.','SmallCustom')]

story += [PageBreak(),p('02 / Results and failure modes','TitleCustom')]
labels={'clean':'Clean','crop4/8':'Aligned crop: 50% area','crop6/8':'Aligned crop: 75% area','offset_crop75_oracle':'Offset crop: ~75% area*','jpeg75':'JPEG Q75','crop4/8+jpeg75':'50% crop + JPEG Q75','crop6/8+jpeg75':'75% crop + JPEG Q75','jpeg50':'JPEG Q50','crop4/8+jpeg50':'50% crop + JPEG Q50','crop6/8+jpeg50':'75% crop + JPEG Q50','noise2':'Gaussian noise, sigma 2','noise5':'Gaussian noise, sigma 5','resize075':'Resize 0.75 and restore','rotate2':'Rotation 2 degrees'}
rows=[['Attack','n / arm','Raw','Repeat','RLNC','MDS']]
for attack,label in labels.items():
    aa=[next(a for a in S['attacks'] if a['attack']==attack and a['method']==m) for m in ['raw_padded','repetition','rlnc','mds']]
    rows.append([label,aa[0]['n'],*[f"{a['recovery_rate']:.1%}" for a in aa]])
story += [p('Metric: exact recovery of all 64 payload bits. Erasures and wrong outputs count as failures. Results below are measured on the synthetic image fixtures.','BodyCustom'),table(rows,[204,55,60,60,60,60])]
story += [p('* Offset crops are 886 x 444 pixels at eight seeded random offsets per payload. The evaluator knows original coordinates and discards partial tiles. This strict whole-tile policy often discards almost all surviving watermark area; the result is a failure of this packetization/extraction policy, not an intrinsic RLNC limit.','SmallCustom')]
story += [h('Separate result: exhaustive packet-erasure model'),Bars(),p('Exactly 4 of 8 packets, all 70 subsets, no image distortion: repetition 16/70; RLNC 69/70; MDS 70/70. The single singular RLNC subset confirms that random coefficients do not guarantee an MDS code. This experiment does not model the spatial correlation of cropping.','SmallCustom')]
story += [p('<b>Uncertainty and detection:</b> paired bootstrap intervals resampled whole fixtures (2,000 draws); all image-suite recovery deltas are 0 with empirical intervals [0,0]. This is not proof of equivalence or population generalization. Among 10 unmarked fixtures, 1 of 80 packets passed CRC, but no full payload was output. Ten negative images cannot establish a low false-positive rate.','SmallCustom')]

story += [PageBreak(),p('03 / Route decision and next gate','TitleCustom')]
story += [h('What to keep, what to change'),p('<b>Keep:</b> a model-independent packet interface, 64-bit useful payload, explicit metadata accounting, CRC-filtered decoding and equal-budget comparisons. Treat DWT-DCT as the low-cost classical baseline and pretrained WAM as the planned neural baseline [1,2].'),p('<b>Change the claim:</b> evaluate "spatial erasure coding for robust image watermarking" rather than presupposing RLNC is best. MDS must remain a main control. If MDS is as good or better at fixed K=4,N=8, select it or explain a separately measured variable-rate advantage for RLNC.'),p('<b>Prioritize:</b> partial-region extraction and unknown-geometry localization. A packet ID cannot locate a region before the watermark bits have been read. WAM supports localized 32-bit messages [2], but eight simultaneously recoverable messages, their CRC survival, and cross-region interference still require measurement.')]
story += [h('Validation gate before a final proposal'),table([['Step','Concrete experiment and acceptance rule'],['1. Restore official backbones','Pin dependencies and checkpoints. First verify clean multi-packet recovery on public natural images with official dwtDct and WAM. Save exact versions and hashes.'],['2. Separate development and test','Use at least 20 natural images for calibration and 100 disjoint natural images for evaluation, three payload seeds each. Select strengths and region sizes on development images only.'],['3. Primary crop endpoint','Test unknown-offset rectangular crops at 25/50/75% retained area and varied aspect ratios, without original-image access or crop coordinates. Report registered-oracle results separately.'],['4. Fair comparison','Compare raw, optimized repetition, RLNC and MDS at equal useful/gross payload, marked area and comparable PSNR/SSIM. Include packet headers, parity and verification overhead.'],['5. Go / no-go','Require >=10 percentage-point mean exact-recovery gain over repetition across the predeclared primary crop cases; paired image-bootstrap lower bound >0; PSNR loss <=0.5 dB and SSIM loss <=0.005. Treat this as a project decision rule, not a proof of universal superiority.'],['6. Validate scope','Repeat on both backbones before claiming model independence. Measure clean negatives, CRC collisions, wrong decoded payloads, runtime, JPEG, resize, rotation and noise; publish failures too.']],[119,380])]
story += [h('Fit to the photographed project brief'),p('The planned system accepts an original image and binary identifier, outputs a watermarked image and recovered payload, and measures imperceptibility plus robustness to JPEG, cropping, rotation and noise. These map directly to the brief. Stable Diffusion and training appear under technical guidance; choosing existing-image watermarking with frozen pretrained weights is an interpretation of that guidance, not confirmed instructor approval. The proposal must state this scope explicitly.'),p('Current status: coding interface and synthetic feasibility test complete; natural-image validation, official backbones, geometric robustness and broad detection validation pending. The final-method gate has not been met.','SmallCustom')]

story += [PageBreak(),p('04 / Reproducibility and sources','TitleCustom')]
story += [h('Files supplied with this report'),table([['File','Purpose'],['src/pilot.py','GF(256) codec, CRC checks, paired evaluation and bootstrap summaries; default official-library path remains unexecuted.'],['src/offline_backend.py','Executable NumPy DWT-DCT-QIM prototype and all ten deterministic fixture generators.'],['EXPERIMENT_PLAN.md','Original protocol and explicit environment amendment recorded before first measurement.'],['results/trials.csv','4,320 image-attack observations with recovery, packet BER, CRC acceptance and wrong-output counts.'],['results/summary.json','Machine-readable configuration, coefficient matrices, quality, attack results and paired differences.'],['results/coding_only.csv','All retained-packet counts: exhaustive subset recovery, kept separate from image results.'],['results/image_manifest.json','Fixture provenance, original shapes and SHA-256 checksums.'],['results/quality.csv / negative_controls.csv','Per-case quality and unmarked-image negative controls.']],[187,312])]
story += [h('Re-run the completed experiment'),p('PILOT_OFFLINE=1 python src/pilot.py','CodeCustom'),p('Requires Python, NumPy and Pillow. The bundled runtime used here was Python 3.12.14. Run from the project root. The program overwrites results in results/. To run the unexecuted natural-image path later, omit PILOT_OFFLINE and install scikit-image and invisible-watermark; dataset downloads may be required. WAM integration is not implemented in this pilot.','SmallCustom')]
story += [h('Verification performed'),p('All four codes passed 20 independently seeded clean payload round trips each. CRC rejected every single-bit flip in their 32-bit packets. All subsets of one to eight packets were enumerated. Actual cropped-array decoding matched cached whole-tile extraction for all four methods. SSIM identity was checked. No wrong payload outputs or wrong accepted packets occurred in attacked watermarked cases; the separate negative-control CRC acceptance is retained in the results.')]
story += [h('Primary references'),p('[1] ShieldMnt. <i>invisible-watermark</i>, official implementation and dwtDct source. <link href="https://github.com/ShieldMnt/invisible-watermark" color="#087F8C">github.com/ShieldMnt/invisible-watermark</link>.','SmallCustom'),p('[2] <i>Watermark Anything with Localized Messages</i>, ICLR 2025. <link href="https://arxiv.org/abs/2411.07231" color="#087F8C">arxiv.org/abs/2411.07231</link>; <link href="https://github.com/facebookresearch/watermark-anything" color="#087F8C">official code and pretrained models</link>.','SmallCustom'),p('[3] Ho et al. <i>A Random Linear Network Coding Approach to Multicast</i>, IEEE Transactions on Information Theory, 2006. <link href="https://authors.library.caltech.edu/records/e9xap-44498" color="#087F8C">Caltech author archive</link>.','SmallCustom'),p('[4] Reed and Solomon. <i>Polynomial Codes Over Certain Finite Fields</i>, 1960. <link href="https://doi.org/10.1137/0108018" color="#087F8C">doi.org/10.1137/0108018</link>.','SmallCustom'),p('[5] Meta. <i>OmniSealBench</i>, official benchmark framework. <link href="https://github.com/facebookresearch/omnisealbench" color="#087F8C">github.com/facebookresearch/omnisealbench</link>. Optional future integration; not used to produce these measurements.','SmallCustom')]
story += [p('References checked 4 October 2026. WAM and OmniSealBench repositories are archived; pin reproducible versions rather than assuming ongoing maintenance. The small pilot establishes neither security nor state-of-the-art performance.','SmallCustom')]

